# Hypothesis: one of these simple colour/checker patches at corners/centre partially triggers the backdoor, revealing target class.
rng=np.random.default_rng(0)
probe_idx=rng.choice(5000,50,replace=False)
base=PRACTICE_IMAGES[probe_idx]
def checker(s,a,b):
    p=np.zeros((s,s,3),np.uint8)
    for i in range(s):
        for j in range(s): p[i,j]=a if (i+j)%2==0 else b
    return p
W=np.array([255,255,255]);K=np.array([0,0,0])
cols={'white':W,'black':K,'red':[255,0,0],'green':[0,255,0],'blue':[0,0,255],'yellow':[255,255,0],'magenta':[255,0,255],'cyan':[0,255,255]}
variants=[]; imgs=[]
for s in [3,5]:
    pats={k:np.tile(np.array(v,np.uint8),(s,s,1)) for k,v in cols.items()}
    pats['chkWB']=checker(s,W,K); pats['chkBW']=checker(s,K,W)
    locs={'TL':(0,0),'TR':(0,32-s),'BL':(32-s,0),'BR':(32-s,32-s),'C':(14,14)}
    for pn,p in pats.items():
        for ln,(r,c) in locs.items():
            x=base.copy(); x[:,r:r+s,c:c+s]=p; imgs.append(x); variants.append((pn,s,ln))
